INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u09-l01','course-a1-foundations','getting-around-town-a1','Getting Around Town','Name common transport and say how to travel around a town.','A1',41,1,'published');
INSERT OR IGNORE INTO questions (id,lesson_id,type,prompt,options_json,answer_key,explanation,position) VALUES
('a1-u09-l01-q01','a1-u09-l01','multiple_choice','Which vehicle travels on rails in a city?','[{"id":"a","text":"tram"},{"id":"b","text":"boat"},{"id":"c","text":"bicycle"}]','a','A tram travels on rails.',1),
('a1-u09-l01-q02','a1-u09-l01','multiple_choice','Which transport travels under a city?','[{"id":"a","text":"underground train"},{"id":"b","text":"taxi"},{"id":"c","text":"bus"}]','a','An underground train travels below the streets.',2),
('a1-u09-l01-q03','a1-u09-l01','multiple_choice','How do you usually travel by bicycle?','[{"id":"a","text":"ride it"},{"id":"b","text":"drive it"},{"id":"c","text":"fly it"}]','a','We ride a bicycle.',3),
('a1-u09-l01-q04','a1-u09-l01','multiple_choice','Complete: I go to work ___ bus.','[{"id":"a","text":"by"},{"id":"b","text":"on"},{"id":"c","text":"at"}]','a','Use by before a means of transport.',4);
