INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u09-l02','course-a1-foundations','at-the-station-a1','At the Station','Understand simple station words and ask about departure times.','A1',42,1,'published');
INSERT OR IGNORE INTO questions (id,lesson_id,type,prompt,options_json,answer_key,explanation,position) VALUES
('a1-u09-l02-q01','a1-u09-l02','multiple_choice','Where can you buy a train ticket?','[{"id":"a","text":"ticket office"},{"id":"b","text":"classroom"},{"id":"c","text":"bakery"}]','a','A ticket office sells tickets.',1),
('a1-u09-l02-q02','a1-u09-l02','multiple_choice','What time does the train leave? asks about ___.','[{"id":"a","text":"departure time"},{"id":"b","text":"the weather"},{"id":"c","text":"the price of lunch"}]','a','Leave means to go from a place.',2),
('a1-u09-l02-q03','a1-u09-l02','multiple_choice','Which sign helps you find your train?','[{"id":"a","text":"platform number"},{"id":"b","text":"bedroom number"},{"id":"c","text":"table number"}]','a','The platform number shows where to board the train.',3),
('a1-u09-l02-q04','a1-u09-l02','multiple_choice','Complete: The train arrives ___ 10:30.','[{"id":"a","text":"at"},{"id":"b","text":"on"},{"id":"c","text":"in"}]','a','Use at with a specific clock time.',4);
