INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u09-l03','course-a1-foundations','buying-tickets-a1','Buying Tickets','Ask for a simple ticket and understand basic ticket information.','A1',43,1,'published');
INSERT OR IGNORE INTO questions (id,lesson_id,type,prompt,options_json,answer_key,explanation,position) VALUES
('a1-u09-l03-q01','a1-u09-l03','multiple_choice','Choose a polite request.','[{"id":"a","text":"A ticket to Baku, please."},{"id":"b","text":"Give ticket now."},{"id":"c","text":"Ticket you give me."}]','a','Please makes the request polite.',1),
('a1-u09-l03-q02','a1-u09-l03','multiple_choice','A return ticket is for ___.','[{"id":"a","text":"going and coming back"},{"id":"b","text":"one journey only"},{"id":"c","text":"a free journey"}]','a','A return ticket includes the journey back.',2),
('a1-u09-l03-q03','a1-u09-l03','multiple_choice','Complete: How ___ is a single ticket?','[{"id":"a","text":"much"},{"id":"b","text":"many"},{"id":"c","text":"old"}]','a','Use how much to ask about a price.',3),
('a1-u09-l03-q04','a1-u09-l03','multiple_choice','Which word means one journey, not there and back?','[{"id":"a","text":"single"},{"id":"b","text":"return"},{"id":"c","text":"platform"}]','a','A single ticket is for one direction.',4);
