INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u09-l04','course-a1-foundations','at-a-hotel-a1','At a Hotel','Use simple phrases for checking in and asking about a hotel room.','A1',44,1,'published');
INSERT OR IGNORE INTO questions (id,lesson_id,type,prompt,options_json,answer_key,explanation,position) VALUES
('a1-u09-l04-q01','a1-u09-l04','multiple_choice','What do you say when you arrive at a hotel?','[{"id":"a","text":"I have a reservation."},{"id":"b","text":"I have a platform."},{"id":"c","text":"I have a timetable."}]','a','A reservation is an arrangement to stay at a hotel.',1),
('a1-u09-l04-q02','a1-u09-l04','multiple_choice','Which item opens a hotel room door?','[{"id":"a","text":"key card"},{"id":"b","text":"bus ticket"},{"id":"c","text":"menu"}]','a','A key card is used to open the room door.',2),
('a1-u09-l04-q03','a1-u09-l04','multiple_choice','Complete: Is breakfast ___ the price?','[{"id":"a","text":"included in"},{"id":"b","text":"near to"},{"id":"c","text":"going by"}]','a','Included in asks whether breakfast is part of the price.',3),
('a1-u09-l04-q04','a1-u09-l04','multiple_choice','Choose a polite request.','[{"id":"a","text":"Could I have another towel, please?"},{"id":"b","text":"You give towel."},{"id":"c","text":"Towel now."}]','a','Could I have is a polite way to ask for something.',4);
