INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u09-l05','course-a1-foundations','travel-information-and-plans-a1','Travel Information and Simple Plans','Ask for basic travel information and describe a simple journey.','A1',45,1,'published');
