('a1-u09-l05-q01','a1-u09-l05','multiple_choice','Which question asks about the place a bus goes to?','[{"id":"a","text":"Where does this bus go?"},{"id":"b","text":"What colour is this bus?"},{"id":"c","text":"Who is this bus?"}]','a','Where asks about destination.',1),
('a1-u09-l05-q02','a1-u09-l05','multiple_choice','Complete: The bus stop is ___ the bank.','[{"id":"a","text":"next to"},{"id":"b","text":"between to"},{"id":"c","text":"under of"}]','a','Next to means beside.',2),
('a1-u09-l05-q03','a1-u09-l05','multiple_choice','What does ''How long does it take?'' ask about?','[{"id":"a","text":"duration"},{"id":"b","text":"ticket colour"},{"id":"c","text":"the driver''s name"}]','a','How long asks about the amount of time.',3),
('a1-u09-l05-q04','a1-u09-l05','multiple_choice','Choose the correct sentence.','[{"id":"a","text":"We are going to the airport tomorrow."},{"id":"b","text":"We going to airport tomorrow."},{"id":"c","text":"We is go to airport tomorrow."}]','a','We are going to is a correct simple future arrangement.',4);
